        assertEquals(10, grid.getTotalRowCount());

        nameFilter.clear();
        statusFilter.deselectItems("ACTIVE", "CLOSED");
        grid.waitForGridToStopLoading();

        url = page.url();
        assertTrue(!url.contains("name=") && !url.contains("status="),
                "Clearing the filter must leave no name/status parameter behind: " + url);
        assertEquals(500, grid.getTotalRowCount());
    }

