+        queryLog.clear();
+    }
+
+    @Test
+    void typingNarrowsTheGridWithoutOneQueryPerKeystroke() {
+        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
+        GridElement grid = GridElement.get(page);
+
+        assertEquals(500, grid.getTotalRowCount());
+
+        queryLog.clear();
+        nameFilter.getInputLocator().pressSequentially("zetterberg");
+        page.waitForTimeout(600);
+        grid.waitForGridToStopLoading();
+
+        assertTrue(queryLog.pageQueries().size() <= 2,
+                "Typing a nine-letter name cost " + queryLog.pageQueries().size()
+                        + " page queries; it must be debounced, not one per keystroke");
+        assertTrue(grid.getTotalRowCount() < 500, "The grid must have narrowed down");
+        assertTrue(page.url().contains("name=zetterberg"), "The address bar must reflect the typed filter: " + page.url());
+    }
+
+    @Test
+    void addressBarReflectsBothFiltersAndClearsWhenEmpty() {
+        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
+        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        GridElement grid = GridElement.get(page);
+
+        nameFilter.getInputLocator().pressSequentially("vir");
+        page.waitForTimeout(600);
+
+        statusFilter.selectItems("ACTIVE", "CLOSED");
+        grid.waitForGridToStopLoading();
+
+        String url = page.url();
+        assertTrue(url.contains("name=vir"), "Expected a name parameter in " + url);
+        assertTrue(url.contains("status=ACTIVE%2CCLOSED") || url.contains("status=ACTIVE,CLOSED"),
+                "Expected status=ACTIVE,CLOSED in " + url);
+        assertEquals(10, grid.getTotalRowCount());
+
+        nameFilter.getInputLocator().press("Control+A");
+        nameFilter.getInputLocator().press("Backspace");
+        page.waitForTimeout(600);
+        statusFilter.deselectItems("ACTIVE", "CLOSED");
+        grid.waitForGridToStopLoading();
+
+        url = page.url();
+        assertTrue(!url.contains("name=") && !url.contains("status="),
+                "Clearing the filter must leave no name/status parameter behind: " + url);
+        assertEquals(500, grid.getTotalRowCount());
+    }
+
+    @Test
+    void openingAUrlWithParametersAppliesAndShowsTheFilter() {
+        page.navigate(getUrl() + "/?name=vir&status=ACTIVE,CLOSED");
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+
+        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
+        MultiSelectComboBoxElement statusFilter = MultiSelectComboBoxElement.getByLabel(page, "Status");
+        GridElement grid = GridElement.get(page);
+        grid.waitForGridToStopLoading();
+
+        nameFilter.assertValue("vir");
+        assertEquals(Set.of("ACTIVE", "CLOSED"), Set.copyOf(statusFilter.getSelectedItems()));
+        assertEquals(10, grid.getTotalRowCount());
+    }
+
+    @Test
+    void keystrokesDoNotEachPushAHistoryEntry() {
+        TextFieldElement nameFilter = new TextFieldElement(page.locator("vaadin-text-field"));
+
+        long before = ((Number) page.evaluate("history.length")).longValue();
+        nameFilter.getInputLocator().pressSequentially("aaltonen");
+        page.waitForTimeout(600);
+        long after = ((Number) page.evaluate("history.length")).longValue();
+
+        assertEquals(before, after, "Typing must not push a new history entry per keystroke");
+    }
+}
